import React, { useState } from 'react';

// === Link Google Fonts (Unbounded & Syne) ===
// Masukkan link ini di file public/index.html di dalam tag <head>, 
// TEPAT DI ATAS tag <title>.
/* <link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Unbounded:wght@400;700;900&family=Syne:wght@400;700;800&display=swap" rel="stylesheet">
*/

const fontHeading = "font-['Syne'] font-extrabold tracking-tighter uppercase";
const fontBody = "font-['Unbounded'] font-light tracking-tight";

const ProfilePage = ({ data, onBack }) => (
  <div className={`animate-in fade-in zoom-in duration-500 max-w-6xl mx-auto py-12 px-6 ${fontBody} selection:bg-black selection:text-white`}>
    <button 
      onClick={onBack} 
      className={`mb-16 inline-flex items-center gap-2 text-sm font-bold border-2 border-slate-900 px-6 py-2 rounded-full hover:bg-slate-900 hover:text-white transition-all shadow-[4px_4px_0px_#111111] ${fontHeading}`}
    >
      <span>←</span> Back to Directory
    </button>

    <div className="flex flex-col lg:flex-row gap-12 items-start relative">
      {/* Ornamen Latar */}
      <div className={`absolute -top-10 -left-10 w-40 h-40 border-[10px] border-slate-900/10 rounded-full z-0`}></div>

      {/* Bagian Foto dengan Frame Hard Shadow */}
      <div className="w-full lg:w-2/5 relative z-10">
        <div className={`p-1.5 rounded-3xl border-4 border-slate-900 shadow-[10px_10px_0px_#111111]`}>
          <div className="rounded-[1.4rem] overflow-hidden aspect-[3/4] bg-white">
            <img src={data.foto} alt={data.nama} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-700" />
          </div>
        </div>
        <div className={`absolute -bottom-8 -left-8 text-7xl opacity-30 ${data.warnaText}`}>✦</div>
      </div>

      {/* Konten Detail */}
      <div className="w-full lg:w-3/5 space-y-12">
        <div className="space-y-4">
          <span className={`inline-block px-4 py-1 border-2 border-slate-900 rounded-lg text-xs font-bold uppercase ${data.warnaText} bg-white shadow-[2px_2px_0px_#111111]`}>
            Student Member
          </span>
          <h1 className={`text-6xl md:text-8xl leading-none ${fontHeading}`}>
            {data.nama.split(' ').map((word, i) => (
              <span key={i} className={i % 2 === 0 ? "text-slate-950" : data.warnaText}>
                {word}<br/>
              </span>
            ))}
          </h1>
          <p className="text-xl font-mono text-slate-500 tracking-wider pt-2">{data.nim}</p>
        </div>

        {/* Bento Box Info Modern */}
        <div className="grid grid-cols-2 gap-6 pt-10 border-t-4 border-slate-900">
          {[
            { label: 'Class / Group', value: data.kelas },
            { label: 'Study Program', value: data.jurusan },
            { label: 'Based In', value: data.domisili },
            { label: 'Faculty', value: "Fakultas Vokasi" }
          ].map((item, index) => (
            <div key={index} className="bg-white border-4 border-slate-900 p-6 rounded-2xl shadow-[6px_6px_0px_#111111]">
              <p className={`text-[10px] uppercase font-bold tracking-[0.2em] mb-2 ${fontHeading}`}>{item.label}</p>
              <p className="text-sm font-semibold text-slate-900 uppercase leading-tight">{item.value}</p>
            </div>
          ))}
        </div>

        {/* Biografi */}
        <div className="relative bg-slate-50 border-4 border-slate-900 p-8 rounded-3xl shadow-[8px_8px_0px_#111111]">
          <p className="text-slate-800 leading-relaxed text-sm md:text-base whitespace-pre-line font-medium italic relative z-10">
            "{data.tentang}"
          </p>
          <div className={`absolute inset-0 bg-gradient-to-br ${data.warna} opacity-10 rounded-3xl z-0`}></div>
          <div className={`absolute -right-5 -bottom-5 text-8xl opacity-30 font-serif ${data.warnaText}`}>”</div>
        </div>
      </div>
    </div>
  </div>
);

export default function App() {
  const [currentPage, setCurrentPage] = useState('home');

  const dataAnggota = [
    {
      id: "anjani-astagina",
      nama: "Anjani Astagina",
      nim: "253140700111035",
      kelas: "T2-A • Group 5",
      jurusan: "Teknologi Informasi",
      domisili: "Malang",
      foto: "/images/anjani.jpeg",
      warna: "from-blue-200 to-cyan-200",
      warnaText: "text-blue-500",
      tentang: "isi biografi kamu di sini minimal 100 kata yaa"
    },
    {
      id: "tzurayya-aisyah",
      nama: "Tzurayya Aisyah",
      nim: "253140700111037",
